  "<c:out value='{}'/> (Click to toggle full text)": "{} (B\u1ea5m \u0111\u1ec3 b\u1eadt/t\u1eaft v\u0103n b\u1ea3n \u0111\u1ea7y \u0111\u1ee7)",
  "A campaign decides who earns a commission and how much. The rule in force when an order is saved is copied onto its commission, so later changes never touch old orders. Only one campaign counts per order (the one paying the most).": "Chi\u1ebfn d\u1ecbch quy\u1ebft \u0111\u1ecbnh ai nh\u1eadn hoa h\u1ed3ng v\u00e0 bao nhi\u00eau. Quy t\u1eafc \u0111ang \u00e1p d\u1ee5ng khi \u0111\u01a1n \u0111\u01b0\u1ee3c l\u01b0u s\u1ebd \u0111\u01b0\u1ee3c sao ch\u00e9p v\u00e0o hoa h\u1ed3ng c\u1ee7a \u0111\u01a1n \u0111\u00f3, n\u00ean thay \u0111\u1ed5i sau n\u00e0y kh\u00f4ng \u1ea3nh h\u01b0\u1edfng \u0111\u01a1n c\u0169. M\u1ed7i \u0111\u01a1n ch\u1ec9 t\u00ednh m\u1ed9t chi\u1ebfn d\u1ecbch (chi\u1ebfn d\u1ecbch tr\u1ea3 nhi\u1ec1u nh\u1ea5t).",
  "A category holds groups and a group holds products, as the cashier sees them on the order screen. A smaller order number shows first.": "Danh m\u1ee5c ch\u1ee9a c\u00e1c nh\u00f3m v\u00e0 nh\u00f3m ch\u1ee9a c\u00e1c s\u1ea3n ph\u1ea9m, \u0111\u00fang nh\u01b0 thu ng\u00e2n th\u1ea5y tr\u00ean m\u00e0n h\u00ecnh t\u1ea1o \u0111\u01a1n. S\u1ed1 th\u1ee9 t\u1ef1 nh\u1ecf h\u01a1n hi\u1ec3n th\u1ecb tr\u01b0\u1edbc.",
  "A code that was already used cannot be deleted. Disable it instead.": "M\u00e3 \u0111\u00e3 \u0111\u01b0\u1ee3c d\u00f9ng th\u00ec kh\u00f4ng x\u00f3a \u0111\u01b0\u1ee3c. H\u00e3y t\u1eaft m\u00e3 thay v\u00ec x\u00f3a.",
  "A commission for that platform order already exists.": "\u0110\u00e3 c\u00f3 hoa h\u1ed3ng cho \u0111\u01a1n tr\u00ean s\u00e0n n\u00e0y.",
  "A company declares this tax by period.": "C\u00f4ng ty k\u00ea khai thu\u1ebf n\u00e0y theo k\u1ef3.",
  "A company pays corporate income tax instead.": "C\u00f4ng ty n\u1ed9p thu\u1ebf thu nh\u1eadp doanh nghi\u1ec7p thay th\u1ebf.",
  "A confirmed payout is locked. A correction needs a separate adjustment, which is not built yet.": "\u0110\u1ee3t chi \u0111\u00e3 x\u00e1c nh\u1eadn b\u1ecb kh\u00f3a. Mu\u1ed1n s\u1eeda ph\u1ea3i l\u00e0m \u0111i\u1ec1u ch\u1ec9nh ri\u00eang, hi\u1ec7n ch\u01b0a c\u00f3 ch\u1ee9c n\u0103ng n\u00e0y.",
  "A device shows ONLINE while it is in service and MAINTENANCE when a technician has taken it out of service. The app cannot see the physical printer, so ONLINE does not prove the hardware is connected.": "Thi\u1ebft b\u1ecb hi\u1ec3n th\u1ecb ONLINE khi \u0111ang ho\u1ea1t \u0111\u1ed9ng v\u00e0 MAINTENANCE khi k\u1ef9 thu\u1eadt vi\u00ean \u0111\u01b0a ra kh\u1ecfi ho\u1ea1t \u0111\u1ed9ng. \u1ee8ng d\u1ee5ng kh\u00f4ng nh\u00ecn th\u1ea5y m\u00e1y in th\u1eadt, n\u00ean ONLINE kh\u00f4ng ch\u1ee9ng minh ph\u1ea7n c\u1ee9ng \u0111\u00e3 k\u1ebft n\u1ed1i.",
  "A fixed commission must be between 0 and 50,000,000 VND.": "Hoa h\u1ed3ng c\u1ed1 \u0111\u1ecbnh ph\u1ea3i t\u1eeb 0 \u0111\u1ebfn 50.000.000 VND.",
  "A group sits inside one category and holds products. You can move a group to another category by changing its category and saving.": "M\u1ed9t nh\u00f3m n\u1eb1m trong m\u1ed9t danh m\u1ee5c v\u00e0 ch\u1ee9a c\u00e1c s\u1ea3n ph\u1ea9m. B\u1ea1n c\u00f3 th\u1ec3 chuy\u1ec3n nh\u00f3m sang danh m\u1ee5c kh\u00e1c b\u1eb1ng c\u00e1ch \u0111\u1ed5i danh m\u1ee5c r\u1ed3i l\u01b0u.",
  "A number from 0 to 9999, or leave empty.": "S\u1ed1 t\u1eeb 0 \u0111\u1ebfn 9999, ho\u1eb7c \u0111\u1ec3 tr\u1ed1ng.",
  "A number from 1 to 50.": "M\u1ed9t s\u1ed1 t\u1eeb 1 \u0111\u1ebfn 50.",
  "A paid commission is locked and never edited.": "Hoa h\u1ed3ng \u0111\u00e3 chi \u0111\u01b0\u1ee3c kh\u00f3a v\u00e0 kh\u00f4ng bao gi\u1edd b\u1ecb s\u1eeda.",
  "A paid obligation can only move to Needs adjustment.": "Ngh\u0129a v\u1ee5 \u0111\u00e3 n\u1ed9p ch\u1ec9 c\u00f3 th\u1ec3 chuy\u1ec3n sang C\u1ea7n \u0111i\u1ec1u ch\u1ec9nh.",
  "A percent cannot be above 100.": "Ph\u1ea7n tr\u0103m kh\u00f4ng \u0111\u01b0\u1ee3c l\u1edbn h\u01a1n 100.",
  "A percentage is at most 50.": "Ph\u1ea7n tr\u0103m t\u1ed1i \u0111a l\u00e0 50.",
  "A percentage is at most 50. A fixed amount is paid once per order.": "Ph\u1ea7n tr\u0103m t\u1ed1i \u0111a l\u00e0 50. S\u1ed1 ti\u1ec1n c\u1ed1 \u0111\u1ecbnh \u0111\u01b0\u1ee3c tr\u1ea3 m\u1ed9t l\u1ea7n cho m\u1ed7i \u0111\u01a1n.",
  "A percentage rate must be between 0 and 100.": "T\u1ef7 l\u1ec7 ph\u1ea7n tr\u0103m ph\u1ea3i t\u1eeb 0 \u0111\u1ebfn 100.",
  "A product that is on an order cannot be deleted. Hide it instead.": "S\u1ea3n ph\u1ea9m \u0111\u00e3 c\u00f3 trong \u0111\u01a1n h\u00e0ng th\u00ec kh\u00f4ng x\u00f3a \u0111\u01b0\u1ee3c. H\u00e3y \u1ea9n n\u00f3.",
  "A reason of at least 5 characters is required.": "C\u1ea7n nh\u1eadp l\u00fd do \u00edt nh\u1ea5t 5 k\u00fd t\u1ef1.",
  "A request is already waiting for the store.": "\u0110\u00e3 c\u00f3 m\u1ed9t y\u00eau c\u1ea7u \u0111ang ch\u1edd c\u1eeda h\u00e0ng x\u1eed l\u00fd.",
  "A required rule is missing or no longer in force for the selected sector.": "Thi\u1ebfu m\u1ed9t quy t\u1eafc b\u1eaft bu\u1ed9c ho\u1eb7c quy t\u1eafc kh\u00f4ng c\u00f2n hi\u1ec7u l\u1ef1c cho ng\u00e0nh \u0111\u00e3 ch\u1ecdn.",
  "A result is a guide, not a legal decision: check it with the tax office or an accountant. The checker never decides from revenue alone: it also needs your business type and registration details, and it says what is still missing.": "K\u1ebft qu\u1ea3 ch\u1ec9 mang t\u00ednh tham kh\u1ea3o, kh\u00f4ng ph\u1ea3i quy\u1ebft \u0111\u1ecbnh ph\u00e1p l\u00fd: h\u00e3y \u0111\u1ed1i chi\u1ebfu v\u1edbi c\u01a1 quan thu\u1ebf ho\u1eb7c k\u1ebf to\u00e1n. H\u1ec7 th\u1ed1ng kh\u00f4ng bao gi\u1edd k\u1ebft lu\u1eadn ch\u1ec9 t\u1eeb doanh thu, m\u00e0 c\u1ea7n c\u1ea3 lo\u1ea1i h\u00ecnh v\u00e0 th\u00f4ng tin \u0111\u0103ng k\u00fd c\u1ee7a b\u1ea1n, v\u00e0 s\u1ebd n\u00f3i r\u00f5 c\u00f2n thi\u1ebfu g\u00ec.",
  "A shared code (no holder) appears in the cashier's discount dropdown on the POS counter. A personal code is assigned to a specific holder.": "M\u00e3 d\u00f9ng chung (kh\u00f4ng c\u00f3 ch\u1ee7) xu\u1ea5t hi\u1ec7n trong danh s\u00e1ch gi\u1ea3m gi\u00e1 c\u1ee7a thu ng\u00e2n \u1edf qu\u1ea7y POS. M\u00e3 c\u00e1 nh\u00e2n \u0111\u01b0\u1ee3c g\u00e1n cho m\u1ed9t ch\u1ee7 c\u1ee5 th\u1ec3.",
