  "Amounts are whole VND, from 0 to 50,000,000. Leave a cost or fee empty for 0.": "S\u1ed1 ti\u1ec1n l\u00e0 VND nguy\u00ean, t\u1eeb 0 \u0111\u1ebfn 50.000.000. \u0110\u1ec3 tr\u1ed1ng chi ph\u00ed ho\u1eb7c ph\u00ed n\u1ebfu l\u00e0 0.",
  "Amounts must be whole VND numbers.": "S\u1ed1 ti\u1ec1n ph\u1ea3i l\u00e0 s\u1ed1 VND nguy\u00ean.",
  "An affiliate sends customers to your store and earns a commission on their orders. At the counter, type the affiliate's referral code on the order screen. The code is printed on the customer's receipt, so everyone can see which code was credited.": "Affiliate d\u1eabn kh\u00e1ch \u0111\u1ebfn c\u1eeda h\u00e0ng v\u00e0 nh\u1eadn hoa h\u1ed3ng tr\u00ean \u0111\u01a1n c\u1ee7a h\u1ecd. T\u1ea1i qu\u1ea7y, nh\u1eadp m\u00e3 gi\u1edbi thi\u1ec7u c\u1ee7a affiliate \u1edf m\u00e0n h\u00ecnh t\u1ea1o \u0111\u01a1n. M\u00e3 \u0111\u01b0\u1ee3c in tr\u00ean h\u00f3a \u0111\u01a1n c\u1ee7a kh\u00e1ch, n\u00ean ai c\u0169ng th\u1ea5y m\u00e3 n\u00e0o \u0111\u01b0\u1ee3c ghi nh\u1eadn.",
  "An affiliate who logs in to the portal needs an account with this same email.": "Affiliate mu\u1ed1n \u0111\u0103ng nh\u1eadp c\u1ed5ng ri\u00eang c\u1ea7n c\u00f3 m\u1ed9t t\u00e0i kho\u1ea3n d\u00f9ng c\u00f9ng email n\u00e0y.",
  "An estimate of the tax to set aside. Not the amount to pay.": "\u01af\u1edbc t\u00ednh kho\u1ea3n thu\u1ebf c\u1ea7n d\u1ef1 tr\u00f9. Kh\u00f4ng ph\u1ea3i s\u1ed1 ti\u1ec1n ph\u1ea3i n\u1ed9p.",
  "An invoice already exists for this order or sale.": "\u0110\u00e3 c\u00f3 h\u00f3a \u0111\u01a1n cho \u0111\u01a1n ho\u1eb7c giao d\u1ecbch b\u00e1n n\u00e0y.",
  "Answer what you know. \"I do not know\" is fine.": "H\u00e3y tr\u1ea3 l\u1eddi nh\u1eefng g\u00ec b\u1ea1n bi\u1ebft. Ch\u1ecdn \"T\u00f4i kh\u00f4ng bi\u1ebft\" c\u0169ng \u0111\u01b0\u1ee3c.",
