  "Flagged amount today": "S\u1ed1 ti\u1ec1n b\u1ecb g\u1eafn c\u1edd h\u00f4m nay",
  "For an online sale use the Create invoice link in the Sales book. For a counter order type its order code.": "V\u1edbi \u0111\u01a1n b\u00e1n online, d\u00f9ng li\u00ean k\u1ebft T\u1ea1o h\u00f3a \u0111\u01a1n trong S\u1ed5 b\u00e1n h\u00e0ng. V\u1edbi \u0111\u01a1n t\u1ea1i qu\u1ea7y, nh\u1eadp m\u00e3 \u0111\u01a1n.",
  "For split payment, cash must be less than order total. If paying 100% cash, please uncheck VietQR.": "V\u1edbi thanh to\u00e1n chia, ti\u1ec1n m\u1eb7t ph\u1ea3i nh\u1ecf h\u01a1n t\u1ed5ng \u0111\u01a1n. N\u1ebfu tr\u1ea3 100% ti\u1ec1n m\u1eb7t, h\u00e3y b\u1ecf ch\u1ecdn VietQR.",
  "Force close (admin)": "\u0110\u00f3ng b\u1eaft bu\u1ed9c (qu\u1ea3n tr\u1ecb)",
  "Force delete": "X\u00f3a b\u1eaft bu\u1ed9c",
  "Forgotten shift? Close immediately without drawer cash audit.": "Qu\u00ean \u0111\u00f3ng ca? \u0110\u00f3ng ngay m\u00e0 kh\u00f4ng ki\u1ec3m ti\u1ec1n trong k\u00e9t.",
  "Four different numbers are kept apart:": "B\u1ed1n con s\u1ed1 kh\u00e1c nhau \u0111\u01b0\u1ee3c t\u00e1ch ri\u00eang:",
  "Four different numbers are kept apart: estimated (our guess), declared (what you filed), confirmed (what the tax office says you owe) and paid (backed by a bank reference or receipt). An obligation is only marked paid when the confirmed amount is covered by payments with evidence.": "B\u1ed1n con s\u1ed1 kh\u00e1c nhau \u0111\u01b0\u1ee3c t\u00e1ch ri\u00eang: \u01b0\u1edbc t\u00ednh (d\u1ef1 \u0111o\u00e1n c\u1ee7a ch\u00fang t\u00f4i), \u0111\u00e3 khai (nh\u1eefng g\u00ec b\u1ea1n \u0111\u00e3 n\u1ed9p t\u1edd khai), x\u00e1c nh\u1eadn (s\u1ed1 c\u01a1 quan thu\u1ebf n\u00f3i b\u1ea1n n\u1ee3) v\u00e0 \u0111\u00e3 n\u1ed9p (c\u00f3 m\u00e3 tham chi\u1ebfu ng\u00e2n h\u00e0ng ho\u1eb7c bi\u00ean lai). M\u1ed9t ngh\u0129a v\u1ee5 ch\u1ec9 \u0111\u01b0\u1ee3c \u0111\u00e1nh d\u1ea5u \u0111\u00e3 n\u1ed9p khi s\u1ed1 ti\u1ec1n x\u00e1c nh\u1eadn \u0111\u01b0\u1ee3c c\u00e1c kho\u1ea3n n\u1ed9p c\u00f3 b\u1eb1ng ch\u1ee9ng bao ph\u1ee7.",
