  "Give a bank reference or a receipt name. Without evidence the payment is refused. The file itself is not stored here.": "H\u00e3y nh\u1eadp m\u00e3 tham chi\u1ebfu ng\u00e2n h\u00e0ng ho\u1eb7c t\u00ean bi\u00ean lai. Kh\u00f4ng c\u00f3 b\u1eb1ng ch\u1ee9ng th\u00ec kho\u1ea3n n\u1ed9p b\u1ecb t\u1eeb ch\u1ed1i. T\u1ec7p th\u1eadt kh\u00f4ng \u0111\u01b0\u1ee3c l\u01b0u \u1edf \u0111\u00e2y.",
  "Give this code to your customers. They (or the cashier) type it on the order screen so the sale is credited to you. Staff affiliates cannot be credited for orders they sell themselves.": "H\u00e3y \u0111\u01b0a m\u00e3 n\u00e0y cho kh\u00e1ch h\u00e0ng. H\u1ecd (ho\u1eb7c thu ng\u00e2n) nh\u1eadp m\u00e3 \u1edf m\u00e0n h\u00ecnh t\u1ea1o \u0111\u01a1n \u0111\u1ec3 \u0111\u01a1n h\u00e0ng \u0111\u01b0\u1ee3c ghi nh\u1eadn cho b\u1ea1n. Affiliate l\u00e0 nh\u00e2n vi\u00ean kh\u00f4ng \u0111\u01b0\u1ee3c ghi nh\u1eadn cho \u0111\u01a1n do ch\u00ednh m\u00ecnh b\u00e1n.",
