  "If the email is registered, we sent a 6-digit code to": "N\u1ebfu email \u0111\u00e3 \u0111\u01b0\u1ee3c \u0111\u0103ng k\u00fd, ch\u00fang t\u00f4i \u0111\u00e3 g\u1eedi m\u00e3 6 ch\u1eef s\u1ed1 \u0111\u1ebfn",
  "If the email is registered, we sent a 6-digit code to {} . It expires in 5 minutes.": "N\u1ebfu email \u0111\u00e3 \u0111\u01b0\u1ee3c \u0111\u0103ng k\u00fd, ch\u00fang t\u00f4i \u0111\u00e3 g\u1eedi m\u00e3 6 ch\u1eef s\u1ed1 \u0111\u1ebfn {} . M\u00e3 h\u1ebft h\u1ea1n sau 5 ph\u00fat.",
