  "Invoice marked as sent to the provider.": "\u0110\u00e3 \u0111\u00e1nh d\u1ea5u h\u00f3a \u0111\u01a1n \u0111\u00e3 g\u1eedi nh\u00e0 cung c\u1ea5p.",
