  "Invoices": "B\u00e1o c\u00e1o",
  "Issuing e-invoices is expected for a company or above the threshold.": "D\u1ef1 ki\u1ebfn ph\u1ea3i xu\u1ea5t h\u00f3a \u0111\u01a1n \u0111i\u1ec7n t\u1eed v\u1edbi c\u00f4ng ty ho\u1eb7c khi v\u01b0\u1ee3t ng\u01b0\u1ee1ng.",
  "It never files a return, pays money or issues an invoice by itself": "Kh\u00f4ng t\u1ef1 n\u1ed9p t\u1edd khai, t\u1ef1 tr\u1ea3 ti\u1ec1n hay t\u1ef1 ph\u00e1t h\u00e0nh h\u00f3a \u0111\u01a1n",
  "It only reads data, never changes data and never writes SQL itself": "Ch\u1ec9 \u0111\u1ecdc d\u1eef li\u1ec7u, kh\u00f4ng s\u1eeda d\u1eef li\u1ec7u v\u00e0 kh\u00f4ng t\u1ef1 vi\u1ebft SQL",
  "Item": "M\u1eb7t h\u00e0ng",
  "Items": "M\u1ee5c",
  "Journey": "H\u00e0nh tr\u00ecnh",
  "Keep tax papers in one place and see what is still missing. Files up to 10 MB: PDF, PNG/JPG images, CSV, Excel and Word. Files are stored in the database and are only downloaded as attachments.": "L\u01b0u gi\u1ea5y t\u1edd thu\u1ebf \u1edf m\u1ed9t n\u01a1i v\u00e0 bi\u1ebft m\u00ecnh c\u00f2n thi\u1ebfu g\u00ec. T\u1ec7p t\u1ed1i \u0111a 10 MB, nh\u1eadn PDF, \u1ea3nh PNG/JPG, CSV, Excel v\u00e0 Word. T\u1ec7p \u0111\u01b0\u1ee3c l\u01b0u trong c\u01a1 s\u1edf d\u1eef li\u1ec7u v\u00e0 ch\u1ec9 t\u1ea3i xu\u1ed1ng d\u01b0\u1edbi d\u1ea1ng t\u1ec7p \u0111\u00ednh k\u00e8m.",
  "Keep your purchases and costs with their documents. A cost is never counted as deductible automatically: you decide, and \"may count\" needs a supporting document. Whether it really reduces tax depends on the rules that apply to you.": "L\u01b0u c\u00e1c kho\u1ea3n mua v\u00e0 chi ph\u00ed c\u00f9ng ch\u1ee9ng t\u1eeb. M\u1ed9t kho\u1ea3n chi kh\u00f4ng bao gi\u1edd \u0111\u01b0\u1ee3c t\u1ef1 \u0111\u1ed9ng t\u00ednh l\u00e0 \u0111\u01b0\u1ee3c kh\u1ea5u tr\u1eeb: b\u1ea1n quy\u1ebft \u0111\u1ecbnh, v\u00e0 \"c\u00f3 th\u1ec3 t\u00ednh\" c\u1ea7n c\u00f3 ch\u1ee9ng t\u1eeb \u0111i k\u00e8m. Vi\u1ec7c n\u00f3 c\u00f3 th\u1eadt s\u1ef1 gi\u1ea3m thu\u1ebf hay kh\u00f4ng c\u00f2n t\u00f9y quy t\u1eafc \u00e1p d\u1ee5ng cho b\u1ea1n.",
