  "Leave empty for a shared code that appears on the POS counter.": "\u0110\u1ec3 tr\u1ed1ng n\u1ebfu l\u00e0 m\u00e3 d\u00f9ng chung xu\u1ea5t hi\u1ec7n \u1edf qu\u1ea7y POS.",
  "Leave empty for unlimited, or enter a number greater than 0.": "\u0110\u1ec3 tr\u1ed1ng n\u1ebfu kh\u00f4ng gi\u1edbi h\u1ea1n, ho\u1eb7c nh\u1eadp s\u1ed1 l\u1edbn h\u01a1n 0.",
  "Leave empty for unlimited.": "\u0110\u1ec3 tr\u1ed1ng n\u1ebfu kh\u00f4ng gi\u1edbi h\u1ea1n.",
