  "The amount after the discount and before VAT. Leave empty for no minimum.": "S\u1ed1 ti\u1ec1n sau gi\u1ea3m gi\u00e1 v\u00e0 tr\u01b0\u1edbc VAT. \u0110\u1ec3 tr\u1ed1ng n\u1ebfu kh\u00f4ng c\u00f3 m\u1ee9c t\u1ed1i thi\u1ec3u.",
  "The amount is above what is still owed (": "S\u1ed1 ti\u1ec1n l\u1edbn h\u01a1n s\u1ed1 c\u00f2n ph\u1ea3i n\u1ed9p (",
