  "This user has history (orders) and cannot be deleted. Lock the account instead.": "Ng\u01b0\u1eddi d\u00f9ng n\u00e0y \u0111\u00e3 c\u00f3 l\u1ecbch s\u1eed (\u0111\u01a1n h\u00e0ng) n\u00ean kh\u00f4ng x\u00f3a \u0111\u01b0\u1ee3c. H\u00e3y kh\u00f3a t\u00e0i kho\u1ea3n thay v\u00ec x\u00f3a.",
