  "Warning: this permanently deletes the category {} , its {} group(s) and its {} product(s). It cannot be undone. Past orders and receipts keep the product names and prices, but the products disappear from the cashier screen and from the Products tab. To only remove a product from sale, hide it on the Products tab instead.": "C\u1ea3nh b\u00e1o: thao t\u00e1c n\u00e0y x\u00f3a v\u0129nh vi\u1ec5n danh m\u1ee5c {} , {} nh\u00f3m v\u00e0 {} s\u1ea3n ph\u1ea9m c\u1ee7a n\u00f3. Kh\u00f4ng th\u1ec3 ho\u00e0n t\u00e1c. \u0110\u01a1n h\u00e0ng v\u00e0 h\u00f3a \u0111\u01a1n c\u0169 v\u1eabn gi\u1eef t\u00ean v\u00e0 gi\u00e1 s\u1ea3n ph\u1ea9m, nh\u01b0ng s\u1ea3n ph\u1ea9m bi\u1ebfn m\u1ea5t kh\u1ecfi m\u00e0n h\u00ecnh thu ng\u00e2n v\u00e0 tab S\u1ea3n ph\u1ea9m. N\u1ebfu ch\u1ec9 mu\u1ed1n ng\u1eebng b\u00e1n m\u1ed9t s\u1ea3n ph\u1ea9m, h\u00e3y \u1ea9n n\u00f3 \u1edf tab S\u1ea3n ph\u1ea9m.",
