  "Turning off this module will stop Tinky from tracking your <strong>1 Billion VND statutory threshold</strong> and will disable proactive threshold warning notifications.": "T\u1eaft module n\u00e0y s\u1ebd d\u1eebng vi\u1ec7c theo d\u00f5i ng\u01b0\u1ee1ng lu\u1eadt \u0111\u1ecbnh <strong>1 t\u1ef7 \u0111\u1ed3ng</strong> v\u00e0 t\u1eaft c\u00e1c th\u00f4ng b\u00e1o c\u1ea3nh b\u00e1o ch\u1ee7 \u0111\u1ed9ng.",
  "Tinky will stop calculating VAT/PIT reserves and alert feeds.": "Tinky s\u1ebd ng\u1eebng t\u00ednh d\u1ef1 ph\u00f2ng thu\u1ebf GTGT/TNCN v\u00e0 ngu\u1ed3n c\u1ea3nh b\u00e1o.",
  "Disabling this module inside Tinky does not relieve your business of its statutory tax declaration and payment obligations under Decree 141/2026/ND-CP and Circular 40/2021/TT-BTC.": "Vi\u1ec7c t\u1eaft module n\u00e0y trong Tinky kh\u00f4ng l\u00e0m mi\u1ec5n tr\u1eeb ngh\u0129a v\u1ee5 k\u00ea khai v\u00e0 n\u1ed9p thu\u1ebf theo Ngh\u1ecb \u0111\u1ecbnh 141/2026/N\u0110-CP v\u00e0 Th\u00f4ng t\u01b0 40/2021/TT-BTC c\u1ee7a c\u1eeda h\u00e0ng.",
  "Disabling this module inside Tinky does <em>not</em> relieve your business of its statutory tax declaration and payment obligations under Decree 141/2026/ND-CP and Circular 40/2021/TT-BTC.": "Vi\u1ec7c t\u1eaft module n\u00e0y trong Tinky <em>kh\u00f4ng</em> l\u00e0m mi\u1ec5n tr\u1eeb ngh\u0129a v\u1ee5 k\u00ea khai v\u00e0 n\u1ed9p thu\u1ebf theo Ngh\u1ecb \u0111\u1ecbnh 141/2026/N\u0110-CP v\u00e0 Th\u00f4ng t\u01b0 40/2021/TT-BTC c\u1ee7a c\u1eeda h\u00e0ng.",
