  "Enable or disable advanced system modules. Core functions (POS, automated bank polling, inventory, shifts, audit logs) remain permanently active.": "B\u1eadt ho\u1eb7c t\u1eaft c\u00e1c module n\u00e2ng cao. C\u00e1c ch\u1ee9c n\u0103ng c\u1ed1t l\u00f5i (POS, qu\u00e9t ng\u00e2n h\u00e0ng t\u1ef1 \u0111\u1ed9ng, kho, ca l\u00e0m, nh\u1eadt k\u00fd) lu\u00f4n lu\u00f4n b\u1eadt.",
  "1 Billion VND revenue threshold tracker, deterministic tax estimation, e-invoice staging, and statutory tax alerts.": "Theo d\u00f5i ng\u01b0\u1ee1ng doanh thu 1 t\u1ef7 \u0111\u1ed3ng, \u01b0\u1edbc t\u00ednh thu\u1ebf ch\u00ednh x\u00e1c, qu\u1ea3n l\u00fd h\u00f3a \u0111\u01a1n \u0111i\u1ec7n t\u1eed v\u00e0 c\u1ea3nh b\u00e1o thu\u1ebf lu\u1eadt \u0111\u1ecbnh.",
  "Shopee and TikTok Shop CSV sales book import, platform commissions, shipping fees, and waterfall net margin calculation.": "Nh\u1eadp s\u1ed5 b\u00e1n h\u00e0ng CSV t\u1eeb Shopee v\u00e0 TikTok Shop, hoa h\u1ed3ng s\u00e0n, ph\u00ed v\u1eadn chuy\u1ec3n v\u00e0 t\u00ednh to\u00e1n d\u00f2ng l\u1ee3i nhu\u1eadn th\u1ef1c.",
