  "Only an order that is still waiting for payment can be linked.": "Ch\u1ec9 c\u00f3 th\u1ec3 g\u00e1n v\u00e0o \u0111\u01a1n h\u00e0ng \u0111ang ch\u1edd thanh to\u00e1n.",
  "The transfer is smaller than the amount the order needs. Close it with Refund needed instead.": "S\u1ed1 ti\u1ec1n chuy\u1ec3n nh\u1ecf h\u01a1n s\u1ed1 ti\u1ec1n \u0111\u01a1n h\u00e0ng c\u1ea7n. H\u00e3y \u0111\u00f3ng giao d\u1ecbch v\u1edbi l\u00fd do C\u1ea7n ho\u00e0n ti\u1ec1n.",
  "Check the order, the category and the note (5 to 200 characters), then try again.": "Ki\u1ec3m tra l\u1ea1i \u0111\u01a1n h\u00e0ng, ph\u00e2n lo\u1ea1i v\u00e0 ghi ch\u00fa (5 \u0111\u1ebfn 200 k\u00fd t\u1ef1), sau \u0111\u00f3 th\u1eed l\u1ea1i.",
  "Another transfer is already linked to this order.": "M\u1ed9t giao d\u1ecbch kh\u00e1c \u0111\u00e3 \u0111\u01b0\u1ee3c g\u00e1n v\u00e0o \u0111\u01a1n h\u00e0ng n\u00e0y.",
  "The low stock level must be a whole number from 0 to 9999.": "Ng\u01b0\u1ee1ng s\u1eafp h\u1ebft h\u00e0ng ph\u1ea3i l\u00e0 s\u1ed1 nguy\u00ean t\u1eeb 0 \u0111\u1ebfn 9999.",
  "1. Total Revenue (Taxable)": "1. T\u1ed5ng doanh thu (Ch\u1ecbu thu\u1ebf)",
