  "Tax Accounting Principle:": "Nguy\u00ean t\u1eafc h\u1ea1ch to\u00e1n thu\u1ebf:",
  "Taxable Revenue (Total Revenue) = Subtotal after seller discounts. Platform deductions (Transaction fees, Commission, Shipping subsidies, Marketing fees) are withheld from wallet payouts (Total settlement amount), but tax regulations do not deduct them from statutory VAT and personal income tax revenue.": "Doanh thu ch\u1ecbu thu\u1ebf (Total Revenue) = Ti\u1ec1n h\u00e0ng sau khi tr\u1eeb voucher shop (Subtotal after seller discounts). C\u00e1c kho\u1ea3n chi ph\u00ed s\u00e0n (Ph\u00ed giao d\u1ecbch, Ph\u00ed hoa h\u1ed3ng s\u00e0n, Ph\u00ed v\u1eadn chuy\u1ec3n, Ph\u00ed ti\u1ebfp th\u1ecb) \u0111\u01b0\u1ee3c kh\u1ea5u tr\u1eeb v\u00e0o ti\u1ec1n quy\u1ebft to\u00e1n v\u1ec1 v\u00ed (Total settlement amount), nh\u01b0ng theo quy \u0111\u1ecbnh thu\u1ebf kh\u00f4ng \u0111\u01b0\u1ee3c gi\u1ea3m tr\u1eeb kh\u1ecfi doanh thu t\u00ednh thu\u1ebf GTGT/TNCN.",
  "Item/SKU variation details are not included in the currently imported files. To activate SKU-level profitability and best-seller matrix, upload a Shopee or TikTok Order Report containing product columns (SKU code, Product name, Quantity).": "Chi ti\u1ebft ph\u00e2n lo\u1ea1i/SKU kh\u00f4ng c\u00f3 trong c\u00e1c t\u1eadp tin \u0111\u00e3 nh\u1eadp. \u0110\u1ec3 k\u00edch ho\u1ea1t b\u1ea3ng ma tr\u1eadn l\u1ee3i nhu\u1eadn theo SKU v\u00e0 s\u1ea3n ph\u1ea9m b\u00e1n ch\u1ea1y, h\u00e3y t\u1ea3i l\u00ean B\u00e1o c\u00e1o \u0111\u01a1n h\u00e0ng Shopee ho\u1eb7c TikTok ch\u1ee9a c\u00e1c c\u1ed9t s\u1ea3n ph\u1ea9m (M\u00e3 SKU, T\u00ean s\u1ea3n ph\u1ea9m, S\u1ed1 l\u01b0\u1ee3ng).",
